import AppKit
import SwiftUI

/// OpenAI / ChatGPT knot mark used by the HUD identity control.
/// The source artwork is the user-supplied official mark reference, normalized to a monochrome template image.
struct OpenAIKnotIcon: View {
    var size: CGFloat = 12

    var body: some View {
        Image(nsImage: Self.image)
            .resizable()
            .interpolation(.high)
            .frame(width: size, height: size)
            .accessibilityHidden(true)
    }

    private static let image: NSImage = {
        let encoded = ""
        guard let data = Data(base64Encoded: encoded), let image = NSImage(data: data) else {
            return NSImage(size: NSSize(width: 1, height: 1))
        }
        image.isTemplate = true
        return image
    }()
}
